  maxAttempts?: number;
  /** Base delay in milliseconds. Default: 100 */
  baseDelayMs?: number;
  /** Maximum delay in milliseconds (bounds the backoff). Default: 5000 */
  maxDelayMs?: number;
  /** Backoff multiplier. Default: 2 */
  factor?: number;
  /**
   * Predicate to decide whether a thrown error is retryable.
   * Non-retryable errors are thrown immediately. Default: retry everything.
   */
  isRetryable?: (error: unknown, attempt: number) => boolean;
  /**
   * Optional jitter factor (0-1) to add randomness and avoid thundering herds.
   * Default: 0 (no jitter)
   */
  jitter?: number;
  /**
   * A signal that, when aborted, cancels the retry loop.
   */
  signal?: AbortSignal;
}

/**
 * Sleeps for the given number of milliseconds, but resolves early if the
 * provided AbortSignal fires.
 */
function sleep(ms: number, signal?: AbortSignal): Promise<void> {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) {
      reject(new DOMException('Aborted', 'AbortError'));
      return;
    }

    const timer = setTimeout(() => {
      cleanup();
      resolve();
    }, ms);
